function totalStrength(strength) {
  const MOD = 1000000007n;
  const n = strength.length;
  const left = new Array(n).fill(-1);
  const right = new Array(n).fill(n);
  const stack = [];
  for (let i = 0; i < n; i++) {
    while (stack.length > 0 && strength[stack[stack.length - 1]] >= strength[i]) {
      right[stack.pop()] = i;
    }
    if (stack.length > 0) {
      left[i] = stack[stack.length - 1];
    }
    stack.push(i);
  }

  const prefix = new Array(n + 1).fill(0n);
  for (let i = 0; i < n; i++) {
    prefix[i + 1] = (prefix[i] + BigInt(strength[i])) % MOD;
  }
  const prefixOfPrefix = new Array(n + 2).fill(0n);
  for (let i = 0; i <= n; i++) {
    prefixOfPrefix[i + 1] = (prefixOfPrefix[i] + prefix[i]) % MOD;
  }

  let total = 0n;
  for (let i = 0; i < n; i++) {
    const startCount = BigInt(i - left[i]);
    const endCount = BigInt(right[i] - i);
    const endSums = prefixOfPrefix[right[i] + 1] - prefixOfPrefix[i + 1];
    const startSums = prefixOfPrefix[i + 1] - prefixOfPrefix[left[i] + 1];
    const groupSums = (startCount * endSums - endCount * startSums) % MOD;
    total = (total + BigInt(strength[i]) * groupSums) % MOD;
  }
  return Number((total + MOD) % MOD);
}

