function totalStrength(strength) {
  let total = 0n;
  for (let start = 0; start < strength.length; start++) {
    let smallest = Infinity;
    let sum = 0;
    for (let end = start; end < strength.length; end++) {
      smallest = Math.min(smallest, strength[end]);
      sum += strength[end];
      total += BigInt(smallest) * BigInt(sum);
    }
  }
  return Number(total % 1000000007n);
}

