function generate(rand, size) {
  const small = size === 'small';
  const n = small ? 1 + Math.floor(rand() * 10) : 2000;
  const top = small ? [3, 10, 1000000000][Math.floor(rand() * 3)] : [5, 1000, 1000000000][Math.floor(rand() * 3)];
  const values = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  const shape = rand();
  if (shape < 0.15) values.sort((a, b) => a - b);
  else if (shape < 0.3) values.sort((a, b) => b - a);
  return [values];
}
